require_once __DIR__.'/config/constants.php';$u=require_login();if(!is_post())redirect('my_order.php');verify_csrf();$id=filter_input(INPUT_POST,'order_id',FILTER_VALIDATE_INT);$reason=trim((string)($_POST['reason']??'Cancelled by customer'));if(!$id)redirect('my_order.php');try{db()->beginTransaction();$s=db()->prepare('SELECT * FROM tbl_order WHERE id=? AND user_id=? FOR UPDATE');$s->execute([$id,$u['id']]);$o=$s->fetch();if(!$o||!can_cancel_order($o))throw new RuntimeException('This order can no longer be cancelled.');$s=db()->prepare('SELECT food_id,quantity FROM tbl_order_item WHERE order_id=?');$s->execute([$id]);foreach($s->fetchAll() as $i){if($i['food_id'])db()->prepare('UPDATE tbl_food SET stock_qty=stock_qty+? WHERE id=?')->execute([$i['quantity'],$i['food_id']]);}$newPayment=$o['payment_status']==='Paid'?'Refunded':($o['payment_status']==='Submitted'?'Failed':$o['payment_status']);db()->prepare("UPDATE tbl_order SET status='Cancelled',cancel_reason=?,cancelled_at=NOW(),payment_status=? WHERE id=?")->execute([$reason,$newPayment,$id]);$s=db()->prepare('SELECT coupon_id FROM tbl_coupon_usage WHERE order_id=?');$s->execute([$id]);if($cid=$s->fetchColumn()){db()->prepare('DELETE FROM tbl_coupon_usage WHERE order_id=?')->execute([$id]);db()->prepare('UPDATE tbl_coupon SET used_count=GREATEST(used_count-1,0) WHERE id=?')->execute([$cid]);}db()->commit();flash('success','Order cancelled. Reserved stock was restored.');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('error',$e->getMessage());}redirect('order-details.php?id='.$id);